#!/usr/bin/env bash
# Writes the Homebrew cask for the macOS desktop app to stdout.
# Usage: desktop-cask.sh VERSION PATH/TO/PR-Manager-macos-arm64.zip
set -euo pipefail
version=${1#v}
sha=$(shasum -a 256 "$2" | cut -d' ' -f1)

cat <<CASK
# This file is generated by scripts/desktop-cask.sh on release. DO NOT EDIT.
cask "pr-manager-desktop" do
  version "$version"
  sha256 "$sha"

  url "https://github.com/amitbet/pr-manager/releases/download/v#{version}/PR-Manager-macos-arm64.zip"
  name "PR Manager"
  desc "Desktop app that sorts pull request changes by the human review they need"
  homepage "https://github.com/amitbet/pr-manager"

  livecheck do
    skip "Auto-generated on release."
  end

  depends_on arch: :arm64
  depends_on formula: [
    "gh",
    "git",
  ]

  app "PR Manager.app"

  # The app is ad-hoc signed but not notarized.
  postflight_steps do
    run "/usr/bin/xattr", args: ["-dr", "com.apple.quarantine", "{{appdir}}/PR Manager.app"]
  end

  caveats <<~EOS
    Run \`gh auth login\` before opening PR Manager.
  EOS
end
CASK
